-- Expanded Straddie Noticeboard and Minjerribah Screen & Media Network starter courses.
-- Update only the original unedited drafts. Published versions and officer edits are preserved.

UPDATE learning_course_versions SET
  description='Make a simple, usable recording and hand its files to the editor.',
  lessons_json=json_array(
    json('{"title":"Check the shoot before rolling","body":"Read the brief and permitted shots, locations and people. Check framing, sound and recording levels with a short test. Agree a way to signal a problem and confirm which filename or slate identifies the take.","captureNotes":"Capture a tabletop demonstration with no private subject or recognisable record. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A test recording has a clean image and distorted voice audio. What do you do first?","choices":[{"id":"a","text":"Record the scene and leave distortion for the editor to repair."},{"id":"b","text":"Use the clean image as evidence that the sound file will be usable."},{"id":"c","text":"Adjust the audio setup and test again before recording the take."}],"correct_choice_id":"c","explanation":"A short test should make both image and audio issues visible.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two takes are called by the same name. What should the shot log do?","choices":[{"id":"a","text":"Give them distinct identifiers and note the relevant sound and image differences."},{"id":"b","text":"Rename only the preferred take and discard the other identifier."},{"id":"c","text":"Leave both with the same name and ask the editor to check timestamps."}],"correct_choice_id":"a","explanation":"Distinct identifiers let the crew and editor discuss the same take.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Log and transfer the takes","body":"Record the useful take names, sound problems and permission restrictions. Make the agreed backup and transfer to the authorised editor. Keep originals and the handover log together.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A backup is made but the transfer lacks take notes. What should be delivered?","choices":[{"id":"a","text":"Only the highest resolution copies to avoid confusion."},{"id":"b","text":"The approved files and a matching log of sound issues, restrictions and backups."},{"id":"c","text":"All files without information so the editor can choose freely."}],"correct_choice_id":"b","explanation":"The log helps the editor use the right source under the right conditions.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"You notice a good take includes a person whose permission is unclear. What goes in the handover?","choices":[{"id":"a","text":"Flag the take and hold that use for review"},{"id":"b","text":"Leave the detail out so the editor can decide from the picture"}],"correct_choice_id":"a","explanation":"The editor needs the restriction alongside the media.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Prepare the shoot, people and permissions","body":"Read the approved shot list, venue, use and restrictions. Confirm check-in, crew responsibilities, any child or cultural permission, gear access, staging and who can pause or adapt the plan. Ask which person handles restricted subjects and how to avoid capturing people or locations outside the brief.\n\nKeep the shot and use scope, owners, hold items and limits in the authorised record.","captureNotes":"Walk through Media network and production brief with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the shot and use scope, owners, hold items and limits using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A participant agrees to audio but the shot list includes their image. What should the crew do?","choices":[{"id":"a","text":"Change the shot plan to the authorised use or ask for separate image clearance."},{"id":"b","text":"Capture the image and flag it so the editor can decide about release."}],"correct_choice_id":"a","explanation":"The operating record needs the shot and use scope, owners, hold items and limits. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a participant’s attendance recorded as general filming permission"},{"id":"b","text":"the shot and use scope, owners, hold items and limits"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Set up, label and verify recordings","body":"Check framing, lighting, storage and the agreed filename or slate. Record and replay a short sound and image test on the intended setup. Check interference, noisy locations, framing and the source subject’s understanding. Swap or adjust as agreed and log changed equipment or coverage needs.\n\nKeep the repeatable setup, playback checks, take identifiers and any known limitation in the authorised record.","captureNotes":"Walk through Camera and sound rehearsal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the repeatable setup, playback checks, take identifiers and any known limitation using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Normal playback is fine but sound distorts during louder speech. What should happen?","choices":[{"id":"a","text":"Take only quiet speech samples and leave loud parts for post-production."},{"id":"b","text":"Adjust for the actual range, then test and listen again before recording an approved take."}],"correct_choice_id":"b","explanation":"The operating record needs the repeatable setup, playback checks, take identifiers and any known limitation. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the repeatable setup, playback checks, take identifiers and any known limitation"},{"id":"b","text":"a photo of the recording screen without an audio test"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Adapt to a changed location or missed take","body":"If a change affects permits, privacy, noise or crew safety, ask the producer or venue lead for a reviewed decision before moving or recording. Capture alternative shots within the approved scope. Maintain room tone and reliability as appropriate, and record why a take was held, changed or should be repeated.\n\nKeep the changed shot, permissions check and footage to use or reshoot in the authorised record.","captureNotes":"Walk through Production call sheet and take log with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the changed shot, permissions check and footage to use or reshoot using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The crew can get a better shot from an unapproved area where other people are visible. What is the useful response?","choices":[{"id":"a","text":"Hold the changed shot and confirm location and participant permissions or use an agreed alternative."},{"id":"b","text":"Record quickly then have the production team decide after the fact."}],"correct_choice_id":"a","explanation":"The operating record needs the changed shot, permissions check and footage to use or reshoot. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a coverage note that assumes all nearby areas are approved"},{"id":"b","text":"the changed shot, permissions check and footage to use or reshoot"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Transfer, back up and return gear","body":"Keep original files and relevant take notes with shared identifiers. Make the agreed backup, check files open and transfer only through the authorised custody path. Give the editor sound or visual problems, use restrictions, credit needs and unrecorded shots. Return and check gear with the owner and log faults or outstanding work.\n\nKeep the checked copies, matching log, authorised recipient, gear return and gaps in the authorised record.","captureNotes":"Walk through Media delivery and equipment handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the checked copies, matching log, authorised recipient, gear return and gaps using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Files have copied but the receiving editor has no take log or restrictions. What closes the handover?","choices":[{"id":"a","text":"Send a folder name and delete the redundant working records."},{"id":"b","text":"Verify the recipient’s files and deliver the matching log, permissions and known defects."}],"correct_choice_id":"b","explanation":"The operating record needs the checked copies, matching log, authorised recipient, gear return and gaps. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the checked copies, matching log, authorised recipient, gear return and gaps"},{"id":"b","text":"a transfer link with no file or permissions tracking"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  practical='Create a fictional three-shot setup and take log. Show permitted people, places and intended uses, a repeatable sound and image test, a decision about a restricted takeover or changed scene, and a checked file transfer with backed-up originals and gear return. Pass when the editor can match files to logs, identify issues and restrictions, and verify exactly what was transferred.',
  edit_version=edit_version+1
WHERE course_id='msmn-camera-sound' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Make a short edit that carries its source, captions and approvals through to delivery.',
  lessons_json=json_array(
    json('{"title":"Assemble a review cut","body":"Start from the agreed brief and authorised files. Keep the originals, identify the revision and mark rough or restricted material for review. Verify that names and dates match the checked sources.","captureNotes":"Capture a fictional timeline and the exported review cut filename. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cut contains an unverified date and a restricted shot. What do you send for review?","choices":[{"id":"a","text":"A labelled work-in-progress with the fact and permission issues clearly flagged."},{"id":"b","text":"The cut as the final export and a verbal note to check it later."},{"id":"c","text":"A file that removes the flags because no one outside the crew can see it yet."}],"correct_choice_id":"a","explanation":"The reviewer needs to know which details still need a decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A name is audible in the edit but captions are misspelled. What do you do?","choices":[{"id":"a","text":"Match only the spelling guessed by speech recognition."},{"id":"b","text":"Check the name against a reliable source and correct the caption timing and text."},{"id":"c","text":"Delete the name from the captions and leave the rest unchecked."}],"correct_choice_id":"b","explanation":"Captions should accurately communicate the recording and verified wording.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Check captions and exports","body":"Check that captions match the spoken words, timing and relevant sounds. Review the output in its intended landscape or portrait layout. Pass the approved source, credits and release conditions to whoever publishes it.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The approved landscape cut is adapted to portrait. What should be checked?","choices":[{"id":"a","text":"Only that the video is the correct aspect ratio."},{"id":"b","text":"Only that the same audio file has been copied."},{"id":"c","text":"Framing, readable captions, credits and whether the new use is approved."}],"correct_choice_id":"c","explanation":"A format change can affect both readability and the authorised use.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which version should move to the publishing step?","choices":[{"id":"a","text":"The newest file automatically"},{"id":"b","text":"The identified reviewed cut with checked captions, credits and permissions"}],"correct_choice_id":"b","explanation":"A later export might still be a working draft.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Set up source versions and an approved editing brief","body":"Confirm intended audience, format, required captions and approval route. Collect only authorised original files and separate private or limited material into the appropriate access area. Match version names, sources and sound or image notes. Use a review cut for testing and keep an edit list of assumptions, permissions and gaps.\n\nKeep the identified source versions, permissions, scope and named reviewer in the authorised record.","captureNotes":"Walk through Production brief and review workspace with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the identified source versions, permissions, scope and named reviewer using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two video files are labelled final and one has unclear permissions. What should the editor do?","choices":[{"id":"a","text":"Select the highest-resolution file and assume the same permissions apply."},{"id":"b","text":"Verify the approved source and restriction before use and keep a version record."}],"correct_choice_id":"b","explanation":"The operating record needs the identified source versions, permissions, scope and named reviewer. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the identified source versions, permissions, scope and named reviewer"},{"id":"b","text":"the newest filenames with no source check"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Review story, sound and captions","body":"Check names, spelling, dates and claims against reliable sources. Listen on the intended setup and check levels against audience needs. Review caption accuracy, timing, readability and relevant sound cues. Use a reviewer who can see both the draft and the verified sources. Hold issues around culturally sensitive or restricted components.\n\nKeep the checked transcript or caption track, source and decisions on anonymity or corrections in the authorised record.","captureNotes":"Walk through Captioning and review cut with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the checked transcript or caption track, source and decisions on anonymity or corrections using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A caption is readable but identifies someone who asked to remain anonymous. What should happen?","choices":[{"id":"a","text":"Correct the identification and recheck the image, audio and caption against the agreed use."},{"id":"b","text":"Keep it because someone who hears the original recording knows the name anyway."}],"correct_choice_id":"a","explanation":"The operating record needs the checked transcript or caption track, source and decisions on anonymity or corrections. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a caption file with a spell-check but no content review"},{"id":"b","text":"the checked transcript or caption track, source and decisions on anonymity or corrections"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Prepare versions for venue, web and portrait use","body":"Agree where each size and version will be used. Recheck aspect ratio, crop, visible credit, caption timing, restrictions and actual playback. Check that a smaller or new audience is within the scope of the approval. Verify the same edit is being approved, and record who can take it down or correct it.\n\nKeep the tested versions, current caption files, approval scope and use restrictions in the authorised record.","captureNotes":"Walk through Screening or publishing delivery with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the tested versions, current caption files, approval scope and use restrictions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The landscape version is cleared but the new portrait edit cuts off captions and contributor credit. What do you do?","choices":[{"id":"a","text":"Release it with a note that viewers can watch the landscape version if needed."},{"id":"b","text":"Fix and test that version and obtain any required clearance before release."}],"correct_choice_id":"b","explanation":"The operating record needs the tested versions, current caption files, approval scope and use restrictions. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the tested versions, current caption files, approval scope and use restrictions"},{"id":"b","text":"export settings and a general cleared tag"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Archive the checked release and hand over corrections","body":"Save the final approved files and their usable source or project reference under the agreed custody. Preserve the clearance, credits, audience, release destinations and current version. Keep superseded versions identifiable and note the owner for corrections, access or withdrawal. Arrange a checked handover and retention decision with the production lead.\n\nKeep a release index, permission and correction trail and retention owner in the authorised record.","captureNotes":"Walk through Filing and next release with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include a release index, permission and correction trail and retention owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A withdrawn clip is found in a promotional folder after the project ends. What should the editor pass on?","choices":[{"id":"a","text":"The affected version and approved response, where it was distributed and who verifies its removal."},{"id":"b","text":"The newest project file only because the original editor is no longer responsible."}],"correct_choice_id":"a","explanation":"The operating record needs a release index, permission and correction trail and retention owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a final zip file without a rights or version record"},{"id":"b","text":"a release index, permission and correction trail and retention owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  practical='Create a review and delivery record for a fictional 45-second community clip. Submit the current script or facts check, media and use restrictions, one corrected caption with timing and credit, verified landscape and portrait or venue delivery checks, and archive and take-down instructions. Pass when the exact approved version, permissions, captions and release destinations can be independently verified.',
  edit_version=edit_version+1
WHERE course_id='msmn-edit-caption' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Work through a proposed screening or workshop before confirming a venue or support.',
  lessons_json=json_array(
    json('{"title":"Work out what you can offer","body":"Describe possible space, availability, people, equipment or support. Ask what the organiser can supply, who will supervise, and what publicity or attribution would be appropriate.","captureNotes":"Use a fictional venue discussion, with the public hosting or participation route on screen. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Check the agreement and follow-up","body":"Discuss access, responsibilities, restrictions, dates, costs and the decision still needed. Agree how the proposed collaboration may be described while the discussion is underway."}'),
    json('{"title":"Agree site use and guest access","body":"Offer the actual space, hours and conditions you can authorise. Check who manages accessibility, security, setup, pack-down and cancellation. Ask the organiser to confirm audience capacity, equipment, production use and what remains subject to the responsible owner.","captureNotes":"Walk through Participation and Places pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Confirm delivery and recognition","body":"Record which event, activity, support or quote was accepted and the exact public wording or sponsor acknowledgement. Identify who can handle a changed plan, insurance or costs, and how a dispute or concern will be routed. Keep provisional support distinct until agreed.","captureNotes":"Walk through Venue and partnership contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Check the site back in and pass on lessons","body":"Agree a condition check, return of keys and gear, incident or accessibility issues, feedback and any correction of public details. Keep the relevant agreement and review date so a successor knows what is still in effect.","captureNotes":"Walk through Venue handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='msmn-host' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Plan the permissions and evidence trail for a story, recorded activity or screening.',
  lessons_json=json_array(
    json('{"title":"Identify the person who can decide","body":"List the material, its source, intended audiences, and who holds relevant permission. Approach the appropriate cultural custodians about cultural material. Ask for the method and scope of review they want.","captureNotes":"Use a fictional permission register without real identities, private files or sensitive knowledge. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Which combination belongs in a useful permission request?","choices":[{"id":"a","text":"Item and a request to authorise every future use by default."},{"id":"b","text":"Item, authority, audience, specific uses and how the person wants to review them."},{"id":"c","text":"Item, a publishing date and the producer''s preferred platform only."}],"correct_choice_id":"b","explanation":"Clear scope lets the right person make an informed decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two people offer conflicting instructions about cultural material. What should the team do?","choices":[{"id":"a","text":"Choose the most convenient instruction in order to finish the edit."},{"id":"b","text":"Record both as permissions and release a shorter version."},{"id":"c","text":"Hold the proposed use and seek direction from the appropriate authorised custodian."}],"correct_choice_id":"c","explanation":"Cultural authority needs to be clear before using the material.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Hand over the limits with the assets","body":"Record what use was agreed, who made the decision, any expiry or review date and what the team must withhold. Give the crew and editor the relevant instruction before capture or release.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Permission covers a community screening and expires before online release. What goes into the handover?","choices":[{"id":"a","text":"The permitted event, time limit and separate decision needed for online release."},{"id":"b","text":"A general approved label since the material was screened once."},{"id":"c","text":"An online export marked suitable if the same footage is used."}],"correct_choice_id":"a","explanation":"Permission changes according to the scope and timing agreed.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Does the producer’s approval cover cultural material by itself?","choices":[{"id":"a","text":"Check for the appropriate custodian’s approval and its scope"},{"id":"b","text":"Treat the production plan as cultural permission"}],"correct_choice_id":"a","explanation":"The appropriate custodian decides the use of cultural material.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Build a scope and authority map","body":"List actual people, locations, clips, music, archival material or cultural knowledge the project wants to use. Identify who is authorised to decide each use. Ask what the person or custodian wishes to allow, who can see it, where it may appear and how future review works. Record material outside the brief as held or excluded.\n\nKeep the scope, item, decision-maker, applicable audience and any unresolved authority in the authorised record.","captureNotes":"Walk through Participation and source pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the scope, item, decision-maker, applicable audience and any unresolved authority using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A contributor can approve their own interview and describes material held by a different custodian. How do you handle it?","choices":[{"id":"a","text":"Treat the contributor’s permission as sufficient for every subject discussed."},{"id":"b","text":"Separate the interview and the cultural material, and obtain direction for the latter from the appropriate authority."}],"correct_choice_id":"b","explanation":"The operating record needs the scope, item, decision-maker, applicable audience and any unresolved authority. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the scope, item, decision-maker, applicable audience and any unresolved authority"},{"id":"b","text":"one general permission for the whole project"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Record separate permissions and review conditions","body":"Distinguish participation, capture, editing, presentation and distribution. Verify that signatures or recorded decisions match each agreed use. Confirm credits, expiry, withdrawal or follow-up and any young participant’s required guardian and safeguarding processes. Keep sensitive details in the appropriate private record and share only the production instructions the crew needs.\n\nKeep a decision for each use, check date, limits and relevant review contacts in the authorised record.","captureNotes":"Walk through Production permission register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include a decision for each use, check date, limits and relevant review contacts using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An authorised contributor clears a class screening but the producer asks for publicity use. What is required?","choices":[{"id":"a","text":"Obtain and record the specific extra permission before making publicity from it."},{"id":"b","text":"Post a shorter version to social media because the class use was already approved."}],"correct_choice_id":"a","explanation":"The operating record needs a decision for each use, check date, limits and relevant review contacts. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a permission box with no specified audience or channel"},{"id":"b","text":"a decision for each use, check date, limits and relevant review contacts"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Check the work at capture, edit and release","body":"Translate the permission record into instructions for the crew and editor. Compare the shot list, copies, credits and final version with the approved scope. Keep any cleared, conditionally usable and held material clearly marked. Ask the authorised people to review proposed changes and verify the exact output that will be distributed.\n\nKeep the item-by-item clearance, reviewed output version and restrictions in the authorised record.","captureNotes":"Walk through Shoot brief and final review with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the item-by-item clearance, reviewed output version and restrictions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The final draft shows an image a custodian allowed only in a working meeting. What follows?","choices":[{"id":"a","text":"Blur part of it and publish without revisiting the scope."},{"id":"b","text":"Hold the image from release and refer any changed use to the proper decision-maker."}],"correct_choice_id":"b","explanation":"The operating record needs the item-by-item clearance, reviewed output version and restrictions. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the item-by-item clearance, reviewed output version and restrictions"},{"id":"b","text":"a general approval attached to an earlier script"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Respond to concerns and maintain custody","body":"When a concern, expiry or withdrawal arrives, identify the exact asset, approved uses, locations and responsible publisher. Ask the appropriate owner to confirm the response. Notify authorised crew, verify corrections or takedowns and update the restricted history. Pass permissions and holds by appropriate scope when the project changes hands.\n\nKeep the decision, all affected uses, verified results and custody or review date in the authorised record.","captureNotes":"Walk through Permission change and handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the decision, all affected uses, verified results and custody or review date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A person changes permission after two outlets received the release. What should be checked?","choices":[{"id":"a","text":"Confirm the required response, affected outlets and who verifies action at each."},{"id":"b","text":"Remove one local copy and treat it as fully withdrawn."}],"correct_choice_id":"a","explanation":"The operating record needs the decision, all affected uses, verified results and custody or review date. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a changed master file without an outlet or audit check"},{"id":"b","text":"the decision, all affected uses, verified results and custody or review date"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  practical='Use a fictional recording with an interview, an archival image and restricted cultural material. Submit a permission map with decision authority, uses, audience, date, expiry or review, instructions for the crew and editor, and a later restriction or withdrawal scenario. Pass when each item is matched to the appropriate decision-maker and every affected use and outlet has an owner for holding, correcting or checking removal.',
  edit_version=edit_version+1
WHERE course_id='msmn-permissions' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Move a proposal from idea to an agreed plan for people, place, equipment and approvals.',
  lessons_json=json_array(
    json('{"title":"Set a workable scope","body":"Write what the project will deliver, the audience and what can fit the available team and resources. Assign someone to confirm the venue, permissions, funding status and each public claim.","captureNotes":"Record a fictional project card beside the public network or funding page. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A venue conversation is positive and the project has a filmmaker. What does a scoped brief still need?","choices":[{"id":"a","text":"The confirmed venue status, permissions owner, crew capacity and costs to check."},{"id":"b","text":"Only a working title and an audience estimate."},{"id":"c","text":"A confirmed public date based on everyone being interested."}],"correct_choice_id":"a","explanation":"A workable production scope identifies its real dependencies.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An edit adds new audience uses that were never discussed. What should the producer do?","choices":[{"id":"a","text":"Treat the approval of the original brief as covering the new uses."},{"id":"b","text":"Ask who can approve the additional uses and record the result before release."},{"id":"c","text":"Send the new version to another channel without updating the permission notes."}],"correct_choice_id":"b","explanation":"New uses may require a new decision from the relevant people.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Hand over the production record","body":"Give the next lead the approved brief, current run sheet, status of permissions, cost assumptions, next decisions and ready contacts. Label prospective partners by their actual level of involvement.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An incoming coordinator sees three versions of the run sheet. What should your handover identify?","choices":[{"id":"a","text":"The newest filename without checking its status."},{"id":"b","text":"The original run sheet only because it was approved once."},{"id":"c","text":"The approved current version and open decisions, with the relevant owners."}],"correct_choice_id":"c","explanation":"The coordinator needs the version that actually governs current work.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"An organisation says it is interested. How should it appear in the plan?","choices":[{"id":"a","text":"As interested until a more specific commitment is agreed"},{"id":"b","text":"As confirmed delivery partner"}],"correct_choice_id":"a","explanation":"The team needs accurate commitments to plan with.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Set scope, budget and actual commitments","body":"Define audience, deliverables, timing, capacity, scope and who is authorised to agree work. Price invoices, equipment, access, participants and contingencies. Distinguish offers, funding estimates and signed commitments. Confirm who can apply for funding or accept a partner offer, how much exposure is open and the decision before announcing.\n\nKeep a scope, cost and cash position with conditions and owners in the authorised record.","captureNotes":"Walk through Network and funding pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include a scope, cost and cash position with conditions and owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A funding illustration is used as proof staff can be hired. What should the producer check?","choices":[{"id":"a","text":"Verify actual funded scope, current commitments, approval and employer before offering work."},{"id":"b","text":"Start assigning roles from the illustration and confirm the budget after filming."}],"correct_choice_id":"a","explanation":"The operating record needs a scope, cost and cash position with conditions and owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a budget graphic used as a funding award"},{"id":"b","text":"a scope, cost and cash position with conditions and owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Organise crew, sites, rights and safeguards","body":"Assign producer, site, screen, story, technical and participant responsibilities and backups. Check venue access and permissions, qualified equipment support, supervision and welfare reporting. Record what needs operator, rights holder or custodian approval. Offer people actual terms and scope before accepting a crew or supplier commitment. Check backup plans and a change decision before opening.\n\nKeep cleared venue and participant conditions, owners and outstanding authority or risks in the authorised record.","captureNotes":"Walk through Production run sheet and participation pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include cleared venue and participant conditions, owners and outstanding authority or risks using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A venue appears suitable but no one can confirm public audience use. What is the producer’s action?","choices":[{"id":"a","text":"Announce the venue because the crew can fit its equipment there."},{"id":"b","text":"Hold the venue status and ask the responsible host or operator to confirm terms and contingency."}],"correct_choice_id":"b","explanation":"The operating record needs cleared venue and participant conditions, owners and outstanding authority or risks. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"cleared venue and participant conditions, owners and outstanding authority or risks"},{"id":"b","text":"a location sketch and presumed permission"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Manage production changes and approvals","body":"Compare actual delivery against schedule, cost, crew, permissions and audience. Identify variance, owner, authorised decision or need to renegotiate. Keep the current brief, versions, safety route and official update accessible to the right crew. For a change, check cost, people, rights, credit and who sees the revised scope before publishing it.\n\nKeep a change record with risks, approvals, owners and affected deliverables in the authorised record.","captureNotes":"Walk through Production decision and review records with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include a change record with risks, approvals, owners and affected deliverables using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A sponsor asks for a new channel late in production. What should be reviewed?","choices":[{"id":"a","text":"The agreement, intended use and approvals for the changed audience, timing and cost."},{"id":"b","text":"Only the new delivery deadline because the sponsor is already in the brief."}],"correct_choice_id":"a","explanation":"The operating record needs a change record with risks, approvals, owners and affected deliverables. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a changed date in the run sheet without scope review"},{"id":"b","text":"a change record with risks, approvals, owners and affected deliverables"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Close production, reporting and ownership","body":"Confirm which outputs were cleared and delivered, check partner acknowledgements, reconcile costs and grant obligations, and follow up on outstanding rights or custody. Arrange storage, archive, retention and equipment return with the responsible owners. Give the successor final versions, next deadlines and private contacts by approved reference. Verify any published correction and unresolved issue status.\n\nKeep the completion position, costs, approved outputs, custody and open tasks in the authorised record.","captureNotes":"Walk through Delivery, archive and handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the completion position, costs, approved outputs, custody and open tasks using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A finished project has unpaid supplier costs and material awaiting rights confirmation. How do you close it?","choices":[{"id":"a","text":"Mark the project closed because the premiere and audience report are finished."},{"id":"b","text":"Record the financial and release exceptions with their authorised owners and keep them open until verified."}],"correct_choice_id":"b","explanation":"The operating record needs the completion position, costs, approved outputs, custody and open tasks. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the completion position, costs, approved outputs, custody and open tasks"},{"id":"b","text":"the distribution link and a declaration that all delivery is complete"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  practical='Plan a fictional short local film with a screening. Submit the scope and budget, crew responsibilities and backup, venue and rights checks, safety and accessibility review, partner status and one approved or pending change. Add delivery and financial close-out, archive custody and open follow-up. Pass when actual commitments are distinguishable, each dependency has appropriate evidence and the successor can take over.',
  edit_version=edit_version+1
WHERE course_id='msmn-producer' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Turn an idea into a short verified story brief with permission to use the material.',
  lessons_json=json_array(
    json('{"title":"Start with the claim and source","body":"List the main facts the story needs, their sources and the people who can verify disputed or unclear details. Label reconstructions and creative elements in your working brief.","captureNotes":"Show a fictional story treatments folder with source and open-question columns. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two sources disagree on a date. What belongs in the brief?","choices":[{"id":"a","text":"The date from the newest document with no mention of the older one."},{"id":"b","text":"The two sources, marked discrepancy and intended authoritative check."},{"id":"c","text":"An average or approximate date that avoids the disagreement."}],"correct_choice_id":"b","explanation":"Open discrepancies need a way to be resolved before a factual claim is used.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A scene recreates something for which no footage exists. How should the draft describe it?","choices":[{"id":"a","text":"Treat it as documentary footage once cut with real interviews."},{"id":"b","text":"Avoid describing the source so viewers can form their own interpretation."},{"id":"c","text":"Clearly label the scene as a reconstruction or creative element."}],"correct_choice_id":"c","explanation":"The review brief needs to show what the production is reconstructing.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Prepare the interview and review","body":"Draft questions, check proposed naming and public uses, agree the review step with the producer and pass on the fact-check list. Keep things the source restricted outside the shared edit.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new interview adds a restricted detail. What should the editor receive?","choices":[{"id":"a","text":"The agreed usable material and a clear instruction about the excluded detail."},{"id":"b","text":"A full transcript and a request to decide which details might be sensitive."},{"id":"c","text":"Only the redacted file, with no indication a restriction needs to carry forward."}],"correct_choice_id":"a","explanation":"The editor needs the relevant limit and usable source material.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"How should a draft label an unverified claim?","choices":[{"id":"a","text":"Write it as a confirmed fact until challenged"},{"id":"b","text":"Flag it for checking with the appropriate source"}],"correct_choice_id":"b","explanation":"The editor must see where evidence is still needed.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Plan the evidence and possible audience use","body":"Write the purpose and intended audience of the story and what sources might support it. Mark assertions, memories and ideas separately, and name the person or source who can check each. Check cultural reference permission and proposal status before relying on private or sensitive material. Agree fact-check and review roles with the producer.\n\nKeep the claim, actual source, status and named check in the authorised record.","captureNotes":"Walk through Sources and participation pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the claim, actual source, status and named check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One source account is widely repeated but no original source is found. What belongs in your draft?","choices":[{"id":"a","text":"Use the repeated account without attribution because it is common knowledge."},{"id":"b","text":"Flag the claim and its verification gap, and arrange a reliable source check before factual release."}],"correct_choice_id":"b","explanation":"The operating record needs the claim, actual source, status and named check. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the claim, actual source, status and named check"},{"id":"b","text":"an undated list of sources with claims presumed true"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Prepare and conduct an authorised interview","body":"Agree the scope, purpose, recording choice and audience with the contributor. Check attribution, review needs, confidentiality and how to pause or stop. Ask open questions and make clear which context depends on private or restricted information. Capture consent and notes through the authorised route and keep identifying material to what is needed.\n\nKeep the planned purpose, consent scope, restrictions and approved storage in the authorised record.","captureNotes":"Walk through Production story and interview brief with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the planned purpose, consent scope, restrictions and approved storage using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A contributor offers a new private detail after agreeing only the earlier topic for release. What should the writer record?","choices":[{"id":"a","text":"The new detail’s restricted status and a separate approval requirement for any intended use."},{"id":"b","text":"Use it because the person agreed to speak for the original interview."}],"correct_choice_id":"a","explanation":"The operating record needs the planned purpose, consent scope, restrictions and approved storage. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the entire interview file represented as cleared"},{"id":"b","text":"the planned purpose, consent scope, restrictions and approved storage"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Verify quotes, claims and version changes","body":"Match quotations and proposed names, dates and claims to the source. Separate fact, commentary and reconstruction. Check current information with the responsible authority, and mark which details need validation. Record review revisions with reasons and credit, identify protected material and track the proposed versus confirmed status of external partners.\n\nKeep the source and checked claim, revision status and reviewer in the authorised record.","captureNotes":"Walk through Script review and sources log with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the source and checked claim, revision status and reviewer using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A revised script makes an interested organisation sound like a confirmed partner. What correction belongs in review?","choices":[{"id":"a","text":"Leave the wording if the organisation has not publicly objected."},{"id":"b","text":"Check the source status and update the wording and change record before release."}],"correct_choice_id":"b","explanation":"The operating record needs the source and checked claim, revision status and reviewer. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the source and checked claim, revision status and reviewer"},{"id":"b","text":"a current script with no notes on changes or verification"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Prepare an editor and publisher handover","body":"Provide the editor with the current approved story outline, usable text and media, source and permission references, attribution, questions still open and what must stay out. Give the publisher the right channel and reviewed status. Agree how future corrections and archive requests will be handled.\n\nKeep the approved copy, verifiable source and permissions with an exceptions owner in the authorised record.","captureNotes":"Walk through Story handover and permissions check with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the approved copy, verifiable source and permissions with an exceptions owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The editor receives a draft with removed material and no explanation. What handover would help?","choices":[{"id":"a","text":"Record the relevant use restriction and cleared version with an approved reference, without sending the private detail."},{"id":"b","text":"Send the removed material so the editor can independently decide."}],"correct_choice_id":"a","explanation":"The operating record needs the approved copy, verifiable source and permissions with an exceptions owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"an export which omits restricted notes and version status"},{"id":"b","text":"the approved copy, verifiable source and permissions with an exceptions owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  practical='Prepare a fictional one-page story treatment, evidence table and interview plan. Include a source conflict, a reconstruction or unconfirmed claim, a cultural or privacy restriction and one verified script revision. Give the editor the cleared version, attribution and the open fact or correction owner. Pass when claims trace to sources, material to be held remains restricted and the review and release steps are clear.',
  edit_version=edit_version+1
WHERE course_id='msmn-research-writer' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Set up an agreed screening, welcome the audience and hand back equipment.',
  lessons_json=json_array(
    json('{"title":"Prepare the run sheet","body":"Confirm the screening and venue decisions with the lead. Allocate projection, sound, audience welcome, accessible seating and pack-down. Ask who can pause or change the programme.","captureNotes":"Record a practice set-up and a fictional crew run sheet. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The run sheet lists audience welcome and AV test at the same time. What should be reviewed?","choices":[{"id":"a","text":"Whether an audience member could cover welcome if people arrive early."},{"id":"b","text":"Whether the AV test can be dropped to simplify the schedule."},{"id":"c","text":"Named crew for each duty, a backup and the timing of their checks."}],"correct_choice_id":"c","explanation":"Critical jobs need enough crew and time to be carried out.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The intended screening file has captions, but no one has checked them on the actual screen. What do you do?","choices":[{"id":"a","text":"Test the file and caption readability with the intended equipment before opening."},{"id":"b","text":"Test only whether the file launches on a laptop."},{"id":"c","text":"Leave caption checking until a viewer asks about it."}],"correct_choice_id":"a","explanation":"A playback check on the equipment verifies the actual experience.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Rehearse failures and close the session","body":"Test the agreed file and captions, then practise what the lead will do if equipment or conditions change. At the end, return gear, report faults and record the handover.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cable fault is discovered during pack-down. What is a useful handover?","choices":[{"id":"a","text":"Return it to the same storage with no tag until the next screen test."},{"id":"b","text":"Identify the item, what happened and who will check or replace it."},{"id":"c","text":"Record only that equipment was returned on time."}],"correct_choice_id":"b","explanation":"A specific fault record helps the next crew avoid an unplanned failure.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Who confirms a public change to the screening plan?","choices":[{"id":"a","text":"Each crew member posting their own version"},{"id":"b","text":"The responsible event lead through the agreed channel"}],"correct_choice_id":"b","explanation":"One confirmed message helps the audience and crew follow the same plan.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Agree the show, permission and responsibility","body":"Confirm approved venue use, capacities, access, rights, version, public timing and accountable show lead. Identify crew, accessible arrival, supply and equipment ownership, safety check and emergency coverage. Agree how to notify volunteers or visitors if the plan changes. Check support requirements with the right people before opening.\n\nKeep the checked scope, venue, rights, crew and stop decision in the authorised record.","captureNotes":"Walk through Screening plan and venue contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the checked scope, venue, rights, crew and stop decision using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A screening is proposed for a booked room but the film permission is pending. What should the crew be told?","choices":[{"id":"a","text":"The venue and permission statuses separately, with a hold until the responsible approval is verified."},{"id":"b","text":"That the booking makes the whole event confirmed."}],"correct_choice_id":"a","explanation":"The operating record needs the checked scope, venue, rights, crew and stop decision. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an event flyer treated as permission and a run sheet"},{"id":"b","text":"the checked scope, venue, rights, crew and stop decision"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Set up and verify the audience experience","body":"Check the exact file and version, projections, captions, audio, seating, access and a clear change or pause plan on the actual equipment. Identify specialist checks and report faults rather than trying to repair outside your role. Confirm crew positioning, the audience welcome and backup. Save the timing and owner for checks that must be repeated.\n\nKeep a tested show copy, checks from the audience area and actual status in the authorised record.","captureNotes":"Walk through Projection, sound and access rehearsal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include a tested show copy, checks from the audience area and actual status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A seated viewer cannot read captions although they work on the laptop. What should happen?","choices":[{"id":"a","text":"Use the laptop playback as the official test result."},{"id":"b","text":"Check audience sightlines and adjust or confirm an appropriate alternative before calling it ready."}],"correct_choice_id":"b","explanation":"The operating record needs a tested show copy, checks from the audience area and actual status. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a tested show copy, checks from the audience area and actual status"},{"id":"b","text":"a list of downloaded files and working equipment"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Manage changes, audience questions and incidents","body":"Use the approved crew cue and check who can pause, reschedule or send public notices. Keep facts consistent across the team. Help people with accessible directions and escalate safety or welfare concerns privately to the responsible contact. Use the agreed incident approach and record whether a public or venue change was actually verified.\n\nKeep the actual change, public message, responsible person and remaining checks in the authorised record.","captureNotes":"Walk through Show cue sheet and event lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the actual change, public message, responsible person and remaining checks using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The screen fails as people arrive and a crew member promises a new start time. What should happen?","choices":[{"id":"a","text":"Have the event lead agree the update and send verified instructions through the established channels."},{"id":"b","text":"Repeat the new time to all guests because a crew member said it."}],"correct_choice_id":"a","explanation":"The operating record needs the actual change, public message, responsible person and remaining checks. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a second unverified start time on an informal sign"},{"id":"b","text":"the actual change, public message, responsible person and remaining checks"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}'),
    json('{"title":"Pack down, report and hand over","body":"Use the agreed safe pack-down, return all gear to named custodians and report faults and missing items. Confirm the site condition, event costs, media custody and restricted incident records through the relevant owners. Collect appropriate feedback and exercise the handover to the next screening team with review dates.\n\nKeep the equipment, custody and incident or follow-up record with owners in the authorised record.","captureNotes":"Walk through Equipment and screening debrief with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/ Include the equipment, custody and incident or follow-up record with owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Something is damaged during pack-down and another event has booked it. What should the next team receive?","choices":[{"id":"a","text":"The booked equipment list with fault details left in someone’s text messages."},{"id":"b","text":"The asset, condition, held status, responsible repair or substitute and next check."}],"correct_choice_id":"b","explanation":"The operating record needs the equipment, custody and incident or follow-up record with owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the equipment, custody and incident or follow-up record with owners"},{"id":"b","text":"a note that the event finished, with no asset condition checks"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://auraofintelligence.github.io/minjerribah-screen-media-network/"]}]}')
  ),
  practical='Submit a fictional screening run sheet with confirmed-format requirements, responsible rights and venue checks, cue and roster, audience access including a caption check, one equipment failure or weather change, and an equipment and debrief handover. Pass when the crew can reproduce the tested setup, communicate one verified change and give custody and follow-up to the right people.',
  edit_version=edit_version+1
WHERE course_id='msmn-screen-crew' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find the public project ideas, connected work, participation routes and sources.',
  lessons_json=json_array(
    json('{"title":"Tour the public pages","body":"Start with the opening page. Follow the network, places, funding and participation pages. Keep project ideas, illustrative budgets and actual invitations distinct in your notes.","captureNotes":"Capture the public site’s navigation and sources page using only material cleared for public viewing. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Pick a route to explore","body":"Choose a story, screen, venue, crew or workshop idea. Use the sources and participation links to find the responsible contact. Check how a named project or organisation describes its own status."}'),
    json('{"title":"Find the right entry point for your idea","body":"Use Network to see connected projects, Places to explore options, Funding to understand planning assumptions and Join to offer a story, skills, space or support. Check Sources when you need evidence or the responsible project’s own contact.","captureNotes":"Walk through MSMN public navigation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Read project and funding status correctly","body":"Look for whether a page labels an idea, prototype, approved activity or confirmed organisation. An illustrative cost or named connection does not establish their agreement or funding. Ask the responsible contact before representing a venue, partner or job as confirmed.","captureNotes":"Walk through Network, Funding and Sources pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Choose and follow up an enquiry","body":"Choose a suitable route to offer interest and state what you can actually provide or would like to learn. Ask what permission, site or model still needs a decision. Keep personal or cultural details out of public submissions and ask for the proper route if needed.","captureNotes":"Walk through Join the build with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='msmn-site-tour' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Bring a local story idea and identify whose knowledge and permissions matter.',
  lessons_json=json_array(
    json('{"title":"Write a first story note","body":"Describe the story, possible audience and why it matters locally. Note who should be asked first and which sources can be verified. Where a story involves cultural knowledge, ask the appropriate custodians about authority and possible uses.","captureNotes":"Capture a made-up pitch card and the public Join the build page. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Agree the boundaries before collecting","body":"Discuss what contributors are willing to share, with whom and in which channels. Record credits and any limits. Ask the responsible producer how to handle material if a person changes their mind."}'),
    json('{"title":"Check your source and proposed purpose","body":"Describe the idea, who might benefit, whether it is documentary or reconstructed and which claims need checking. Identify those who have cultural authority or permission to discuss the source. Ask first rather than recording private details in a public pitch.","captureNotes":"Walk through Join and source brief with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Agree how people may participate","body":"Confirm what a contributor is comfortable with, who can see it, how it may be credited, and any restrictions or review. Check separately before capturing, changing purpose or sharing, and agree how concerns can be raised.","captureNotes":"Walk through Story permission conversation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Follow the story through review","body":"Check the reviewed wording, facts, credited contributions and intended audience. Give the producer the correct source and note what should be held. Ask how to report a mistake or changed permission and where any approved copy will be kept.","captureNotes":"Walk through Producer or editor contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='msmn-story-contributor' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Choose a practical starter task and agree supervision, equipment and feedback.',
  lessons_json=json_array(
    json('{"title":"Find a starter task","body":"Select something small enough to practise during a workshop, such as logging a take, checking a caption or writing a shot description. Confirm who will demonstrate it and provide feedback.","captureNotes":"Show a fictional workshop list and chosen task card. Reference site: https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Finish with a useful handover","body":"Return equipment and describe what you produced, where it is kept and whether it cleared review. Ask what you should practise next. Agree separately whether you can use any work in a portfolio."}'),
    json('{"title":"Agree a useful assignment and support","body":"Choose an age and skill appropriate job with a demonstrator, check-in and safe equipment. Ask what the result should look like, how to get assistance and what not to capture. Clarify whether the workshop is learning, volunteering or a role with separate work arrangements.","captureNotes":"Walk through Workshop or production lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Use authorised equipment and material","body":"Confirm equipment custody and whom to tell about a broken tool or unclear instruction. Use approved faces, files and locations only. Ask about project naming, permitted access and where to place a first draft. Keep the supervisor informed before changing the assignment.","captureNotes":"Walk through Crew briefing and work area with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}'),
    json('{"title":"Finish with evidence and feedback","body":"Return equipment and show the output, source or file reference, what was checked and what still needs review. Agree the next skill to practise, and ask about portfolio use and credit separately. Route a workplace, privacy or welfare concern to the designated person.","captureNotes":"Walk through Trainee handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://auraofintelligence.github.io/minjerribah-screen-media-network/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='msmn-trainee' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare clear business information and nominate who can approve corrections.',
  lessons_json=json_array(
    json('{"title":"Choose information people can act on","body":"Check a public business listing or service-hours notice. State the business name, location, hours, source and end date for a temporary change. Confirm who can speak for the business.","captureNotes":"Use the public business directory and a made-up closure or opening-hours change. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cafe will close early this Thursday only. What should the notice say?","choices":[{"id":"a","text":"The regular business hours with the temporary change in an unlabelled note."},{"id":"b","text":"The new hours as an indefinite listing until the business changes them again."},{"id":"c","text":"The affected location and date, revised hours, source and expiry."}],"correct_choice_id":"c","explanation":"A time-limited change should be specific enough for visitors to act on.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two staff members send conflicting hours. What should happen before review?","choices":[{"id":"a","text":"Ask the nominated business contact to confirm the current hours and source."},{"id":"b","text":"Use whichever set of hours matches last month''s listing."},{"id":"c","text":"Publish a range of both hours and wait for people to report an issue."}],"correct_choice_id":"a","explanation":"The business contact can resolve which information is authoritative.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review permission before offering it","body":"Get approval for the selected outlet, contact details and images. Give the reviewer a way to check the details and tell them which person will confirm changes or request removal.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The business approves text for web and TV but asks to exclude its image from TV. What do you send?","choices":[{"id":"a","text":"A single combined version that the venue can shorten if needed."},{"id":"b","text":"Outlet-specific versions and the image restriction in the reviewer copy."},{"id":"c","text":"The version with no image restrictions because the wording is the same."}],"correct_choice_id":"b","explanation":"Approval can vary by both channel and asset.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"When a temporary notice ends, what should the reviewer have?","choices":[{"id":"a","text":"An instruction to keep showing it until someone complains"},{"id":"b","text":"A clear expiry and a contact who can confirm the next update"}],"correct_choice_id":"b","explanation":"A clear expiry prevents out-of-date information from carrying on.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Confirm signing rights and the public record","body":"Identify the actual business and who can issue hours, prices, venue or event messages. Check the information against the responsible contact and the public source that the reviewer can verify. Agree who may handle complaints or corrections and which contact details may be published.\n\nKeep an issuer reference, checked time and open correction owner in the authorised record.","captureNotes":"Walk through Businesses and draft editor with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include an issuer reference, checked time and open correction owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two staff give different temporary hours. With a draft due soon, what should be sent?","choices":[{"id":"a","text":"Send the version verified by the nominated issuer with its source and effective date, or hold it for their decision."},{"id":"b","text":"Choose the version last received and mark the time provisional in the internal record only."}],"correct_choice_id":"a","explanation":"The operating record needs an issuer reference, checked time and open correction owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a forwarded message without responsibility or a current source"},{"id":"b","text":"an issuer reference, checked time and open correction owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Set expiry, outlets and public attribution","body":"Select agreed outlets and prepare readable copy for each. Give a temporary notice a clear active window and expiry. Keep personal contacts, unpublished prices or images without the right permission outside the release. Check the actual business credit and where a customer can verify the update.\n\nKeep the approved outlet variants, expiry and credits in the authorised record.","captureNotes":"Walk through Draft editor and outlet preview with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the approved outlet variants, expiry and credits using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The business agreed web publication but the TV preview looks clearer. What should happen?","choices":[{"id":"a","text":"Send the TV copy as well since both use the same wording."},{"id":"b","text":"Keep the TV version in review until its outlet and any image use are agreed."}],"correct_choice_id":"b","explanation":"The operating record needs the approved outlet variants, expiry and credits. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the approved outlet variants, expiry and credits"},{"id":"b","text":"a single generic export with no scope or expiry"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Respond to a correction or withdrawal","body":"Check the business’s revised information and notify the reviewer or steward using the original notice ID and agreed new scope. State the exact time it changes and ask for the actual published outcome. If a venue screen is still wrong, contact the relevant host and keep the issue open until they verify it.\n\nKeep the change request and outlet verification with a named follow-up in the authorised record.","captureNotes":"Walk through Publishing guide and approved reviewer with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the change request and outlet verification with a named follow-up using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A stale sale message is still visible after the new notice was approved. What goes into your report?","choices":[{"id":"a","text":"The original notice ID, actual affected outlet, observed copy and the confirmed correction or withdrawal."},{"id":"b","text":"The approved new notice alone because it proves every display updated."}],"correct_choice_id":"a","explanation":"The operating record needs the change request and outlet verification with a named follow-up. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a new draft treated as proof the old one was removed"},{"id":"b","text":"the change request and outlet verification with a named follow-up"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Handle public questions and hand over publisher duties","body":"Answer from the verified business source and route any privacy, accessibility or complaint concern to the responsible person. Maintain the approval and expiry record for future offers, and give the successor the approved account scope, public contact, open notices and timing to review them. Keep other staff details out of the public feed.\n\nKeep the checked publisher scope, open notice IDs and correction route in the authorised record.","captureNotes":"Walk through Business contact and publishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the checked publisher scope, open notice IDs and correction route using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A customer reports a wrong listing while the designated issuer is away. What should the handover provide?","choices":[{"id":"a","text":"Access to the previous publisher’s account so any staff member can edit."},{"id":"b","text":"The agreed backup and correction authority, notice reference and verification status."}],"correct_choice_id":"b","explanation":"The operating record needs the checked publisher scope, open notice IDs and correction route. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the checked publisher scope, open notice IDs and correction route"},{"id":"b","text":"an export of saved drafts with no current contact or expiry"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Use a fictional temporary hours notice with two outlets, a change and an expiry. Submit the original and revised copy, issuer and scope evidence, approved contact and image decision, and a log showing what must be verified on the affected displays. Include a named backup and follow-up. Pass when every public field can be traced to the issuer, outlet permissions are respected and an outdated copy has a verification owner.',
  edit_version=edit_version+1
WHERE course_id='noticeboard-business-publisher' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Draft a useful notice and share it with the right person for review.',
  lessons_json=json_array(
    json('{"title":"Prepare a draft","body":"Open the draft editor. Write a clear headline, place, start time, expiry and the public source. Include only the contact information and images agreed for publication.","captureNotes":"Show the browser draft editor and a fictional arts-night notice. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Choose the outlets","body":"Select where you would like the notice to appear: web, venue TV or touch kiosk. Preview each requested outlet and give the approved reviewer a review copy with those choices."}'),
    json('{"title":"Agree authority, permissions and an audience","body":"Work out who can issue the notice, which contact may be public and whose permission is needed for an image, quotation or venue. Agree the intended outlets and keep private rosters and source or permission records with the authorised reviewer.","captureNotes":"Walk through Draft editor and publishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Prepare a reviewer handover","body":"Check the source, place, useful time, expiry and legibility in each intended outlet. Include the name or role who can verify changes and any outlet-specific exclusions. Send the review copy through the agreed channel and keep track of which version you sent.","captureNotes":"Walk through Review copy and board preview with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Check corrections and take-downs","body":"When details change, contact the responsible reviewer with the original notice reference, confirmed new information, effective time and outlets. Ask what to do if an outdated version is still showing. Check the real display or ask the host before treating it as corrected.","captureNotes":"Walk through Publishing guide and public board with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='noticeboard-community-contributor' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Check the source, scope and approval of a notice before authorising display.',
  lessons_json=json_array(
    json('{"title":"Review against the original","body":"Match the draft with the named public source. Check the place, timing, publisher approval and permissions for people and images. Compare the content against the intended outlet and return unclear items to the issuer.","captureNotes":"Capture a fictional draft and reviewed example from the public publishing guide. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The event flyer and draft disagree about the start time. How do you review it?","choices":[{"id":"a","text":"Ask the issuer to confirm its current source and resolve the mismatch first."},{"id":"b","text":"Use the draft''s time because it reached review later than the flyer."},{"id":"c","text":"Use the flyer time and leave the mismatch out of the decision record."}],"correct_choice_id":"a","explanation":"A reviewer should resolve the discrepancy with the responsible issuer.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A public photo is linked but its reuse permissions are unclear. Which action fits?","choices":[{"id":"a","text":"Approve the photo on a venue screen only because it will be seen briefly."},{"id":"b","text":"Ask for a cleared image or send the wording for review without the image."},{"id":"c","text":"Approve the image if the issuer can promise someone will check later."}],"correct_choice_id":"b","explanation":"The media permission must be clear for the planned use.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Check each update","body":"Agree the revised wording and effective time. Record who reviewed it and when, the intended outlets and the expiry. Tell the steward and venue contact how to check a correction or withdrawal.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A revised notice should take effect in ten minutes. What goes in the review record?","choices":[{"id":"a","text":"The replacement text and no timing because a future check will catch changes."},{"id":"b","text":"Only the new time, with the old version left up until its expiry."},{"id":"c","text":"Agreed wording, effective time, outlets, expiry, reviewer and how hosts check it."}],"correct_choice_id":"c","explanation":"A correction needs clear coordination and verification for the affected outlets.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The copy asks for kiosk display but the issuer approved only web. What do you do?","choices":[{"id":"a","text":"Ask for confirmation or keep the approval to web"},{"id":"b","text":"Add it to the kiosk because the format fits"}],"correct_choice_id":"a","explanation":"Approval covers the agreed outlets.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Triage the issuer and permission evidence","body":"Match the request to the person or organisation able to issue the notice. Check the original source, audience, rights or permission, contact and time every relevant fact was checked. Flag uncertain or sensitive details for the correct reviewer and keep private approval evidence out of the public feed.\n\nKeep the issuer and source checks, restricted evidence reference and decision status in the authorised record.","captureNotes":"Walk through Publishing guide and reviewer records with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the issuer and source checks, restricted evidence reference and decision status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The notice arrived from a familiar volunteer but the responsible venue has not confirmed it. What is the next step?","choices":[{"id":"a","text":"Confirm the venue’s source and approval before clearing the notice as theirs."},{"id":"b","text":"Approve with the volunteer named as fallback issuer."}],"correct_choice_id":"a","explanation":"The operating record needs the issuer and source checks, restricted evidence reference and decision status. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a familiar sender’s email and a ready-to-post banner"},{"id":"b","text":"the issuer and source checks, restricted evidence reference and decision status"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review copy by channel and accessibility","body":"Check the title, locality, dates, time zone, contact and legibility on each approved outlet. Look for confusing date or status text, excessive personal information or images cleared for a different use. Verify changes to wording and return issues with an owner. Include the start and take-down times in the reviewed record.\n\nKeep the checked copy and permissions for each outlet, plus expiry in the authorised record.","captureNotes":"Walk through Web, venue TV and kiosk previews with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the checked copy and permissions for each outlet, plus expiry using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A short TV version removes the qualification that the time is proposed. What should the reviewer do?","choices":[{"id":"a","text":"Clear it as long as the web wording is accurate."},{"id":"b","text":"Restore the actual status or hold the TV version until correct and approved."}],"correct_choice_id":"b","explanation":"The operating record needs the checked copy and permissions for each outlet, plus expiry. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the checked copy and permissions for each outlet, plus expiry"},{"id":"b","text":"a signed web review applied to every format"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Handle urgent or official-source updates","body":"During a disruption identify the responsible official issuer, checked time and affected area. Use the source and approved fallback for those affected. Do not rewrite uncertainty into instructions. Escalate uncertain or conflicting sources to the responsible authority. Keep stale or unverifiable copies distinguishable and record who can correct them.\n\nKeep the current source, affected outlets, checked time and correct status in the authorised record.","captureNotes":"Walk through Emergency information and publishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the current source, affected outlets, checked time and correct status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A cached local notice conflicts with current official directions. What should be reviewed first?","choices":[{"id":"a","text":"Follow the current responsible authority and initiate a correction with its source and time."},{"id":"b","text":"Choose the local copy because it gives more precise instructions."}],"correct_choice_id":"a","explanation":"The operating record needs the current source, affected outlets, checked time and correct status. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a repost with no issuer or last check time"},{"id":"b","text":"the current source, affected outlets, checked time and correct status"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Record decisions, corrections and review continuity","body":"Keep the reviewer, scope, effective time, version, reason and expiry for clear, return or withdraw outcomes. Hand the cleared record to the authorised steward and arrange host verification for an affected notice. Log the next check for still-open outlets and privately route any complaint or permission change to the right owner.\n\nKeep the review decision, feed or display verification and unresolved handoff in the authorised record.","captureNotes":"Walk through Pilot feed review and host check with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the review decision, feed or display verification and unresolved handoff using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A withdrawal has been cleared but a host is offline. How do you record this?","choices":[{"id":"a","text":"Close the check because the review withdraw action is complete."},{"id":"b","text":"Record the authorised withdrawal and keep display verification open with a named host and next check."}],"correct_choice_id":"b","explanation":"The operating record needs the review decision, feed or display verification and unresolved handoff. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the review decision, feed or display verification and unresolved handoff"},{"id":"b","text":"a review decision labelled displayed everywhere"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Review a fictional event notice with a time mismatch, an uncleared image, requested outlets and a later withdrawal. Submit findings, reviewer decision and reason for each issue, the checked source and expiry, and a handoff showing what the steward and each host will verify. Include how to follow an official alert if sources conflict. Pass when every approved copy is accurate, within scope and traceable to the proper issuer and decision.',
  edit_version=edit_version+1
WHERE course_id='noticeboard-editorial-review' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Maintain approved records and hand over corrections, expiry and take-downs.',
  lessons_json=json_array(
    json('{"title":"Prepare the approved record","body":"From the reviewed copy, confirm the stable notice ID, source, responsible publisher, time checked, expiry and agreed outlets. Use the practice guide to rehearse a change under the same ID.","captureNotes":"Show the public practice board with a staged feed example. Keep write access and credentials private. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An approved draft has an ID but no public source. What do you do?","choices":[{"id":"a","text":"Use the practice board URL as a substitute source."},{"id":"b","text":"Return it for a verifiable source before preparing the approved feed record."},{"id":"c","text":"Use a private review link as the public source so there is a link."}],"correct_choice_id":"b","explanation":"The public source should allow the responsible notice information to be checked.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A notice is withdrawn and one host is offline. What belongs in the handover?","choices":[{"id":"a","text":"A note that withdrawn means every screen is already clear."},{"id":"b","text":"A copy of the last approved notice so the venue can restore it."},{"id":"c","text":"The withdrawal, affected outlets, verification gap and who will check the offline display."}],"correct_choice_id":"c","explanation":"The feed decision and the visible screen state need separate verification.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Promote and verify a correction","body":"Follow the current authorised publishing process. Have the relevant host confirm what is actually showing. Record a take-down or withdrawal and escalate when the feed or display cannot be checked.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An updated feed has the right date but an old venue remains on a screen. What''s the next check?","choices":[{"id":"a","text":"Check the affected display and state with its host against the current record."},{"id":"b","text":"Retire the corrected notice and create a new record without checking the device."},{"id":"c","text":"Assume the screen shows an unrelated notice and close the issue."}],"correct_choice_id":"a","explanation":"The host can help check the actual outlet and whether it has the current record.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"The time changes for the same event. How should the steward identify it?","choices":[{"id":"a","text":"Create a duplicate notice and leave the first one live"},{"id":"b","text":"Keep the notice ID and record a fresh review and correction"}],"correct_choice_id":"b","explanation":"A stable identity helps remove the outdated version from the same locations.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Validate and stage an authorised feed record","body":"Check the stable notice ID, approved state, issuer, place, category, public HTTPS source, scope and timing against the reviewed copy. Keep private evidence outside the distributed file. Validate the current feed schema and timestamp fields in a test build. Use the correct outlet identifiers for approved channels and verify each intended preview before scheduling release.\n\nKeep the approved review, valid feed fields, checked preview and version reference in the authorised record.","captureNotes":"Walk through Pilot feed and publishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the approved review, valid feed fields, checked preview and version reference using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft lists an approved notice but there is no named reviewer or source. What should the steward do?","choices":[{"id":"a","text":"Use the steward name in place of the reviewer because the register has been checked."},{"id":"b","text":"Return it for the missing evidence before including it in the checked public feed."}],"correct_choice_id":"b","explanation":"The operating record needs the approved review, valid feed fields, checked preview and version reference. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the approved review, valid feed fields, checked preview and version reference"},{"id":"b","text":"a feed row with missing provenance and scope"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Release and verify actual outlets","body":"Use the authorised release process, save the release or commit reference and confirm the board, venue TV and kiosk show only their agreed records. Ask hosts to verify visible wording, timing and status. Track disconnected devices separately. Record any mismatch and when the next outlet check will happen.\n\nKeep the checked deployment, per-outlet result and affected host or issue in the authorised record.","captureNotes":"Walk through Pilot board and participant screens with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the checked deployment, per-outlet result and affected host or issue using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"All previews worked but a participating screen is not showing a changed notice. What should the steward record?","choices":[{"id":"a","text":"Check the actual device with its host and track the mismatch and last verified state."},{"id":"b","text":"Close the release because previews are evidence that the published record is visible."}],"correct_choice_id":"a","explanation":"The operating record needs the checked deployment, per-outlet result and affected host or issue. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a build success label with no display verification"},{"id":"b","text":"the checked deployment, per-outlet result and affected host or issue"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Correct, expire and withdraw safely","body":"Use the stable ID and fresh issuer or reviewer clearance for a correction. Preserve the scope unless a later decision changes it and verify the old notice is no longer visible. Remove or mark a withdrawn record using the current process. For expiry check the actual device and what appears if the feed is unavailable. Retain historical review evidence in the appropriate place.\n\nKeep the previous and new versions, reviewed scope, timing and verified removal in the authorised record.","captureNotes":"Walk through Pilot feed update and review register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the previous and new versions, reviewed scope, timing and verified removal using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A notice is renewed for web but the old TV version was never cleared for renewal. What needs doing?","choices":[{"id":"a","text":"Renew for all outlets and rely on the next routine host review."},{"id":"b","text":"Preserve the approved change scope and confirm the old TV display expires or is withdrawn as directed."}],"correct_choice_id":"b","explanation":"The operating record needs the previous and new versions, reviewed scope, timing and verified removal. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the previous and new versions, reviewed scope, timing and verified removal"},{"id":"b","text":"a newly added duplicate notice with no relationship to the old copy"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Maintain fallbacks, recovery and the handover","body":"Record stale, disconnected and fallback outcomes, distinguishing the board’s service state from official emergency direction. Check backup and recovery with the authorised technical and venue owners. Give a successor release steps and safe rollback evidence, current issuers, contacts, open checks and upcoming expiries. Verify the authorised backup can restore a tested release without revealing private data.\n\nKeep current release and recovery status, outstanding removals and responsible owners in the authorised record.","captureNotes":"Walk through Screens and outages and emergency sources with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include current release and recovery status, outstanding removals and responsible owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A rollback restores an old notice that has since been withdrawn. What is the response?","choices":[{"id":"a","text":"Contain the affected display and restore or release the verified current record, then verify the affected outlets."},{"id":"b","text":"Keep the rolled-back version because the website is operational."}],"correct_choice_id":"a","explanation":"The operating record needs current release and recovery status, outstanding removals and responsible owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a backup version reference without rechecking withdrawal state"},{"id":"b","text":"current release and recovery status, outstanding removals and responsible owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Rehearse adding, correcting, expiring and withdrawing a fictional pilot notice with web and kiosk approval and one disconnected host. Provide the staged records, validation and visible outlet checks, release reference, fallback or rollback plan and a log with unresolved display owners. Pass when the same ID carries the change, private review material stays outside the public record and each visible outlet has verified state or a named open check.',
  edit_version=edit_version+1
WHERE course_id='noticeboard-feed-steward' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Check screen uptime and record which device, notice and connection need follow-up.',
  lessons_json=json_array(
    json('{"title":"Check display, connection and source","body":"Use the practice display to identify the device, outlet, last check and feed state. Compare it with a current source and report what appears on the actual screen.","captureNotes":"Record the public practice screen and one fictional offline rehearsal. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A screen is powered but it shows an old notice. What do you investigate first?","choices":[{"id":"a","text":"The display, last successful check and whether the feed contains the current record."},{"id":"b","text":"Replace the screen immediately because old content always indicates a device fault."},{"id":"c","text":"Change the notice wording independently in the feed."}],"correct_choice_id":"a","explanation":"Checking the actual display and source helps locate the fault.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Two screens report issues after a connection change. What does the log need?","choices":[{"id":"a","text":"One common fault name so both can be marked fixed together."},{"id":"b","text":"Distinct device and venue details, time, symptoms, checks and escalation owner."},{"id":"c","text":"Only the venue Wi-Fi name and a screenshot from the better screen."}],"correct_choice_id":"b","explanation":"Separate device records give owners something to verify.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Log the fault and return to service","body":"Record the time, observed status and who owns the response. Follow the agreed local checklist. Verify the display and notify the venue or steward when the checked service is restored.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The screen has reconnected. What completes a return-to-service check?","choices":[{"id":"a","text":"See that the screen turns on and close the report."},{"id":"b","text":"Wait until someone reports a fresh problem before checking content."},{"id":"c","text":"Verify a current notice and visible display state, then tell the responsible contacts."}],"correct_choice_id":"c","explanation":"A powered and connected device still needs its displayed content checked.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"A connection is down. What should you pass on first?","choices":[{"id":"a","text":"A claim that the feeder service has recovered"},{"id":"b","text":"What the display shows, when checked and the responsible contact"}],"correct_choice_id":"b","explanation":"The recorded observation lets the responsible person decide what to do.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Commission with venue and operator agreement","body":"Check whose equipment and location it is, agreed format and outlet, opening hours, accessible viewing, support contacts and power or connection responsibilities. Refer installation and electrical checks to the appropriate people. Record device identity and test expected display, stale warning and approved fallback before it is used.\n\nKeep a device and venue record with permitted operation and owner in the authorised record.","captureNotes":"Walk through Setup and hosting guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include a device and venue record with permitted operation and owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A device is installed but its venue has not agreed operating hours or responsibility. What do you do?","choices":[{"id":"a","text":"Keep commissioning open until the agreed custody, operating and support checks are in place."},{"id":"b","text":"Mark it live because it can display a test notice."}],"correct_choice_id":"a","explanation":"The operating record needs a device and venue record with permitted operation and owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a screen image and power-on status with no operating agreement"},{"id":"b","text":"a device and venue record with permitted operation and owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Run routine checks and outage triage","body":"At opening or the agreed interval check device, connection, clock, last checked feed and visible notice against the current source. Label observations as current, cached or unavailable using the agreed fallback. Log time, location, display and what was checked. Escalate suspected power, mounting or safety faults to the appropriate person.\n\nKeep the observed state, comparison and escalation owner in the authorised record.","captureNotes":"Walk through Screens and outages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the observed state, comparison and escalation owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The display is on and shows stale content. What should be compared before the issue is closed?","choices":[{"id":"a","text":"Its most recent power-on time and whether the screen lights up."},{"id":"b","text":"The device time, last successful feed, visible notice and the current issuer or steward record."}],"correct_choice_id":"b","explanation":"The operating record needs the observed state, comparison and escalation owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the observed state, comparison and escalation owner"},{"id":"b","text":"a broad report saying the screen works"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Verify receipts, corrections and return to service","body":"Test a correction, expiry and fallback response with approved practice content. On reconnection verify the live approved record, update time and affected outlet against the current source. If a host cannot reach the screen, record that display verification is still open. Confirm restoration with the steward and venue contact rather than closing on a network signal alone.\n\nKeep the tested correction and restored display, time checked and named contacts in the authorised record.","captureNotes":"Walk through Screen and current source with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the tested correction and restored display, time checked and named contacts using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The signal returns but a withdrawn notice still appears. What do you do?","choices":[{"id":"a","text":"Keep the content issue open, contact the steward and verify the affected screen no longer shows it after correction."},{"id":"b","text":"Close it because connectivity has returned and an update should follow."}],"correct_choice_id":"a","explanation":"The operating record needs the tested correction and restored display, time checked and named contacts. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a restored Wi-Fi status with no content check"},{"id":"b","text":"the tested correction and restored display, time checked and named contacts"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Hand over maintenance, equipment and support","body":"Provide the asset or venue owner, setup records, fallback steps, condition, review date and outstanding faults. Include where approved instructions and backups live and who can act if replacement or specialist service is required. Arrange a test of the next operator’s access and contact route. Preserve event and incident records in the agreed place.\n\nKeep the equipment fault and maintenance history, authorised access and next check in the authorised record.","captureNotes":"Walk through Venue log and setup checklist with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/ Include the equipment fault and maintenance history, authorised access and next check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A caretaker change leaves an intermittent fault with no owner. What belongs in the handover?","choices":[{"id":"a","text":"The device login and an informal note that the fault usually clears."},{"id":"b","text":"The device and fault, observed evidence, remaining operating condition and assigned owner and check date."}],"correct_choice_id":"b","explanation":"The operating record needs the equipment fault and maintenance history, authorised access and next check. This lets the next person verify the work and any remaining decision.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the equipment fault and maintenance history, authorised access and next check"},{"id":"b","text":"device details with no owner or unresolved issues"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Use a fictional venue screen and record a commissioning, stale content and reconnection drill. Include ownership, agreed operating scope, device and display checks, safe escalation, verified correction and fallback, handover and maintenance owner. Pass when the recipient can distinguish power, connectivity and actual visible content and reproduce the check with the steward and venue contact.',
  edit_version=edit_version+1
WHERE course_id='noticeboard-screen-caretaker' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Learn where to find local notices, use the practice board and see who issues important updates.',
  lessons_json=json_array(
    json('{"title":"Find a public notice","body":"Open the homepage, then visit the board and try a filter. Read the named publisher, place, source and expiry before relying on the information. Look at the training page for the practice workflow.","captureNotes":"Capture the public board and training page using a fictional notice. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Follow a changed plan","body":"Compare a notice with its public source. If a transport or official warning matters to your plans, check the issuing agency directly. Send a correction or question to the responsible contact."}'),
    json('{"title":"Recognise examples and checked notices","body":"Check whether the example banner, sample board or reviewed feed is showing. Open the notice, follow its issuer and check place, start, expiry and any recent change. A practice notice shows how the network works and should be read in that context.","captureNotes":"Walk through Practice board and reviewed pilot board with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Use the right source during disruptions","body":"For an alert or transport change, follow the current issuing authority or operator. Check timestamp and what area it applies to. If a display is offline or stale, follow the available official source and report the mismatch to the host or notice contact.","captureNotes":"Walk through Emergency information and island travel with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Choose a route to help","body":"Use the draft editor or training exercise to learn how to contribute, and the host or business route when you can provide a place or service. Confirm who can review and publish a real notice. Use the authorised contact for corrections and keep private information off public drafts.","captureNotes":"Walk through Submit, training and hosting pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='noticeboard-site-tour' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare to host a public screen and agree who maintains it.',
  lessons_json=json_array(
    json('{"title":"Agree what the screen is for","body":"Identify the host contact, audience, allowed outlets, local notices and opening hours. Work through power, connectivity, physical access and equipment responsibility before confirming a trial.","captureNotes":"Capture the public hosting or pilot page and a fictional venue setup. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Check what visitors actually see","body":"Practise opening the display, identifying when it was checked and reporting an issue. Agree how staff handle a stale notice, an unavailable feed and an official warning."}'),
    json('{"title":"Agree the service, equipment and site responsibilities","body":"Agree venue status, expected audience, accessible location, hours, approved outlets, maintenance, custody and how staff learn to check it. Identify who can approve content and who is responsible for fitting or specialist checks. Keep the actual agreement and confirm which items are still part of a proposal.","captureNotes":"Walk through Businesses, setup and hosting with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Check opening, faults and stale notices","body":"Ask the nominated staff to check current notice, feed status and when the screen was last verified. Know what to show if it cannot be checked and when to notify the steward or caretaker. During an incident refer to the authoritative source, using the agreed venue fallback for visitors.","captureNotes":"Walk through Screen and outage guidance with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Receive corrections and hand over hosting","body":"When a notice changes or is withdrawn, confirm what viewers see and report any remaining old copy. Record when checks occur, who receives faults and where the agreement and maintenance record are. At transition confirm custody, review dates and private support contacts.","captureNotes":"Walk through Venue log and publishing guide with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='noticeboard-venue-host' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Point visitors to sources and practise a safe handover when plans change.',
  lessons_json=json_array(
    json('{"title":"Check in and find the current briefing","body":"Confirm the lead, location and duty. Compare the welcome briefing with the current source before directing a visitor. Know how to contact the venue and the notice steward.","captureNotes":"Use the public visitor and volunteer rehearsal. Leave real guest information off-screen. Reference site: https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Hand over a change","body":"Report the old and new instructions, source, time checked and unresolved question to the lead. Ask them to confirm the wording visitors should use while a screen is offline."}'),
    json('{"title":"Prepare a shift and agree its limits","body":"Find the shift lead, check-in location, task, visitor information sources and accessibility contacts. Confirm which work you can do on the day and who handles a technical outage, privacy or safety concern. Keep private roster or visitor details within the agreed process.","captureNotes":"Walk through Visitor and volunteer rehearsal with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Handle changed information","body":"Check a changed time, entrance or travel note with the responsible source and the lead before directing visitors. If a display is offline, use the agreed fallback and its last checked status. Escalate an urgent issue through the named route and avoid giving instructions beyond the confirmed information.","captureNotes":"Walk through Volunteer welcome and official sources with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}'),
    json('{"title":"Close the shift and transfer the next action","body":"Pass on the current location, source, when checked, unverified issues and who can decide them. Return any equipment and ask who can verify any agreed voluntary contribution record. Report concerns or personal matters privately to the responsible person.","captureNotes":"Walk through Volunteer handover and venue contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://straddie-noticeboard-cloudflare.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='noticeboard-welcome-volunteer' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;
